"""qf_visuals hyperframes backend.

Builds a minimal standalone HyperFrames composition (per hyperframes-core
contract + skills/heygen-hyperframes/SKILL.md) from a Script: one .clip per
scene, 1080x1920, single paused GSAP timeline animating inner nodes only.

Render via `npx hyperframes render`; any failure raises RuntimeError so the
pipeline can fall back to Pillow cards (pipeline never breaks on stage).
"""

from __future__ import annotations

import html
import shutil
import subprocess
from pathlib import Path

W, H = 1080, 1920


def total_duration(script, secs_per_image: float) -> float:
    return round(len(script.scenes) * secs_per_image, 2)


def build_composition(script, out_dir: str | Path, secs_per_image: float = 2.5) -> str:
    out = Path(out_dir)
    out.mkdir(parents=True, exist_ok=True)
    total = total_duration(script, secs_per_image)
    clips = []
    for i, s in enumerate(script.scenes):
        start = round(i * secs_per_image, 2)
        clips.append(f"""
    <div class="clip" data-start="{start}" data-duration="{secs_per_image}" data-track-index="{i}">
      <div class="card scene-{i}" id="qf-scene-{i}">
        <div class="badge">QONEQT&nbsp;&nbsp;{i + 1}/{len(script.scenes)}</div>
        <div class="title">{html.escape(s.title.upper())}</div>
        <div class="caption">{html.escape(s.caption)}</div>
        <div class="vo">{html.escape(s.voiceover)}</div>
        <div class="foot">Qoneqt Global Feed&nbsp;&nbsp;9:16</div>
      </div>
    </div>""")
    index = f"""<!doctype html>
<html><head><meta charset="utf-8" />
<style>
  html,body {{ margin:0; padding:0; background:#0b0b12; }}
  #root {{ width:100%; height:100%; position:relative; overflow:hidden;
    background:linear-gradient(180deg,#1a1033 0%,#2b1a5e 45%,#0e2a5e 100%); }}
  .clip {{ position:absolute; inset:0; }}
  .card {{ position:absolute; inset:0; padding:120px 80px; color:#fff;
    font-family:Arial,Helvetica,sans-serif; }}
  .badge {{ display:inline-block; background:#fff; color:#14141c; font-weight:700;
    font-size:40px; padding:14px 28px; border-radius:24px; }}
  .title {{ font-size:88px; font-weight:800; line-height:1.05; margin-top:180px; }}
  .caption {{ font-size:54px; color:#ffe878; margin-top:60px; }}
  .vo {{ font-size:38px; color:#e6e6f0; margin-top:50px; line-height:1.4; }}
  .foot {{ position:absolute; bottom:110px; left:80px; font-size:36px; color:#c8c8d6; }}
</style>
<script src="https://cdnjs.cloudflare.com/ajax/libs/gsap/3.12.5/gsap.min.js"></script>
</head><body>
<div data-composition-id="qf" data-width="{W}" data-height="{H}" data-duration="{total}" id="root">
{''.join(clips)}
</div>
<script>
  (function () {{
    var tl = gsap.timeline({{ paused: true }});
    {''.join(f'tl.fromTo("#qf-scene-{i} .title", {{opacity:0, y:40}}, {{opacity:1, y:0, duration:0.6}}, {round(i * secs_per_image, 2)});' for i in range(len(script.scenes)))}
    {''.join(f'tl.fromTo("#qf-scene-{i} .caption", {{opacity:0, y:24}}, {{opacity:1, y:0, duration:0.5}}, {round(i * secs_per_image + 0.3, 2)});' for i in range(len(script.scenes)))}
    window.__timelines = window.__timelines || {{}};
    window.__timelines["qf"] = tl;
  }})();
</script>
</body></html>
"""
    p = out / "index.html"
    p.write_text(index)
    return str(p)


def render_composition(comp_dir: str | Path, out_mp4: str | Path) -> str:
    npx = shutil.which("npx")
    if not npx:
        raise RuntimeError("npx not found on PATH (need Node 22+ for hyperframes render)")
    out = Path(out_mp4)
    out.parent.mkdir(parents=True, exist_ok=True)
    cmd = [npx, "hyperframes", "render", "--project", str(comp_dir), "--output", str(out)]
    p = subprocess.run(cmd, capture_output=True, text=True, timeout=600)
    if p.returncode != 0 or not out.exists():
        tail = ((p.stderr or "") + (p.stdout or ""))[-2000:]
        raise RuntimeError(f"hyperframes render failed: {tail}")
    return str(out)
